16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.samples.petclinic.model.Luhn;
19	import org.springframework.stereotype.Component;
20	
21	import java.nio.charset.StandardCharsets;
22	import java.security.MessageDigest;
23	import java.security.NoSuchAlgorithmException;
24	
25	/**
26	 * Formats an owner's {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}, where {@code REGION}
27	 * is the owner's region code, {@code FY} is the two-digit fiscal year (starting 1 July) that
28	 * contains the registration date, {@code HASH8} is the first eight upper-case hex characters of
29	 * the SHA-256 digest over the owner's identity ({@code normalizedTelephone + lastName}), and
30	 * {@code CHK} is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}
31	 * (e.g. {@code 'NSW26A1B2C3D4' + CHK}).
32	 */
33	@Component
34	public class MemberIdGenerator {
35	
36	    /** Number of leading hex characters of the SHA-256 digest kept as the hash segment. */
37	    private static final int HASH_LENGTH = 8;
38	
39	    /**
40	     * Build the member id from the owner's region, fiscal year and identity.
41	     *
42	     * @param region              the owner's region code (the leading {@code <REGION>} segment)
43	     * @param fiscalYear          the two-digit fiscal year (0-99) of the registration date
44	     * @param normalizedTelephone the owner's telephone in its canonical (E.164) form
45	     * @param lastName            the owner's last name
46	     * @return the formatted member id {@code '<REGION><FY><HASH8><CHK>'}
47	     */
48	    public String generate(String region, int fiscalYear, String normalizedTelephone, String lastName) {
49	        String base = String.format("%s%02d%s", region, fiscalYear, hash(normalizedTelephone + lastName));
50	        return base + Luhn.checkDigit(base);
51	    }
52	
53	    private String hash(String identity) {
54	        byte[] digest = sha256(identity);
55	        StringBuilder hex = new StringBuilder(HASH_LENGTH);
56	        for (int i = 0; hex.length() < HASH_LENGTH; i++) {
57	            hex.append(String.format("%02X", digest[i]));
58	        }
59	        return hex.substring(0, HASH_LENGTH);
60	    }
61	
62	    private byte[] sha256(String value) {
63	        try {
64	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
65	        }
66	        catch (NoSuchAlgorithmException e) {
67	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
68	        }
69	    }
70	}
