21	/**
22	 * Derives an owner's locality — the canonical region. The postcode range is preferred
23	 * (see {@link RegionPostcodes#regionForPostcode(String)}); only when the postcode is
24	 * absent or in no known range does a fixed city-to-region table decide. Owners that
25	 * resolve by neither route yield {@link #UNKNOWN}.
26	 */
27	public final class Locality {
28	
29	    /** Locality returned for any city not present in the table. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private static final Map<String, String> CITY_TO_REGION = Map.of(
33	        "Sydney", "NSW",
34	        "Melbourne", "VIC",
35	        "Brisbane", "QLD");
36	
37	    /** The canonical regions this application recognises. */
38	    private static final Set<String> KNOWN_REGIONS = Set.copyOf(CITY_TO_REGION.values());
39	
40	    private Locality() {
41	    }
42	
43	    /**
44	     * Whether the given region is one of the canonical known regions (NSW, VIC or QLD).
45	     * Returns {@code false} for {@code null}, {@link #UNKNOWN} or any other value.
46	     */
47	    public static boolean isKnownRegion(String region) {
48	        return KNOWN_REGIONS.contains(region);
49	    }
50	
51	    /**
52	     * Derives the region for an owner, preferring the postcode range and falling back to
53	     * the city-to-region table. Returns {@link #UNKNOWN} for a {@code null} owner or when
54	     * neither route resolves a region.
55	     */
56	    public static String forOwner(Owner owner) {
57	        if (owner == null) {
